using System.Collections.Concurrent;
using System.Text.Json;
using CombatSolver.Engine.InCombat.Simulation;
using MegaCrit.Sts2.Core.Entities.Players;
using MegaCrit.Sts2.Core.Models;
using MegaCrit.Sts2.Core.Models.Cards;
using MegaCrit.Sts2.Core.Models.Potions;
using MegaCrit.Sts2.Core.Models.Powers;

namespace CombatSolver;

internal static class JointInventoryObserver
{
    private static readonly ConcurrentDictionary<string,long> Counts = new();
    private static readonly ConcurrentDictionary<CombatRootSnapshot,string> RootRejections = new();
    private static long _queryTicks;
    static JointInventoryObserver()
    {
        AppDomain.CurrentDomain.ProcessExit += (_,_) =>
        {
            string? path = Environment.GetEnvironmentVariable("COMBATSOLVER_JOINT_PROBE_OUTPUT");
            if (path is null) return;
            File.WriteAllText(path,JsonSerializer.Serialize(new
            {
                counts=Counts.OrderBy(p=>p.Key).ToDictionary(p=>p.Key,p=>p.Value),
                queryMilliseconds=(double)_queryTicks*1000/System.Diagnostics.Stopwatch.Frequency,
                scope="Read-only diagnostic; cumulative observer wall time, not CPU or performance acceptance",
            },new JsonSerializerOptions {WriteIndented=true}));
        };
    }
    private static void Count(string key) => Counts.AddOrUpdate(key,1,static (_,n)=>n+1);
    internal static void Observe(CombatRootSnapshot root, SearchPolicySnapshot policy,
        DirectSearchPurpose? purpose, int minimum, int? maximum, PotionFreePolicyBaseline? baseline,
        SolverPotionPolicy effectivePotionPolicy, PotionStrategySnapshot strategy,
        Player player, SearchNode node, BossHpRelief relief)
    {
        if (purpose != DirectSearchPurpose.SmartPotionGradient || minimum < 1 || maximum != minimum)
            return;
        Count("exact-gradient-visits");
        if (policy.PotionPolicy != SolverPotionPolicy.Smart
            || effectivePotionPolicy != SolverPotionPolicy.RequireAtLeastOne || strategy.HasForcedDirectives
            || policy.EffectiveGrowthBudgets != default || policy.RelicTargets.Count != 0
            || policy.TheftPolicy == SolverTheftPolicy.PreserveResources)
        { Count("policy-rejected"); return; }
        if (baseline is not {Won:true,DeathSaveUseCount:0} win)
        { Count("complete-baseline-rejected"); return; }
        if (root.ClosedPotionInventory is not { } stock)
        {
            string reason=RootRejections.GetOrAdd(root, static capturedRoot =>
            {
                var captured=capturedRoot.ForkSimulator();
                return StrategicHpRecoveryBound.ComponentRootSourceRejection(captured,capturedRoot.PlayerIdentity,
                    requireClosedPotionInventory:true,acceptAdditionalInitialCard: static card =>
                        card.GetType()==typeof(BundleOfJoy)||card.GetType()==typeof(Entropy))
                    ?? "post-source-capture-guard";
            });
            Count("stock-rejected:"+reason);return;
        }
        if (node.IsTerminal || !node.Snapshot.HasSimulator || node.Snapshot.HasRisk
            || node.Snapshot.BoundaryReason != SearchBoundaryReason.None)
        { Count("unstable-rejected"); return; }
        long began = System.Diagnostics.Stopwatch.GetTimestamp();
        try
        {
            var sim = (CombatPredictionSimulator)node.Snapshot.Simulator;
            var combat = (SimulatedCombatState)sim.State.CombatState;
            int certified = StrategicHpRecoveryBound.ComponentHealingUpperBound(sim,player,0,
                includePotionHealing:false);
            if (certified == int.MaxValue || stock.MinimumExplicitCost(sim,player,minimum,certified) is not { } stockCost)
            { Count("unknown-component-or-stock"); return; }
            long active = 0;
            foreach (var power in combat.EffectivePowers())
                if (power.GetType() == typeof(RegenPower) && ReferenceEquals(power.Owner,player.Creature))
                    active += Math.Max(0,power.Amount);
            // Check extraction against the existing semantic bound, rather than
            // silently interpreting any other finite recovery as regeneration.
            if (StrategicHpRecoveryBound.RegenerationHealingUpperBound(active,0) != certified)
            { Count("unmodelled-recovery"); return; }
            int slots = ((CombatSolver.Engine.Common.ICombatPredictionPlayerLimits)combat).GetPotionSlotCount(player);
            int used = combat.PotionUses.Count(static u=>!u.Automatic);
            int needed = Math.Max(0,minimum-used);
            if (slots > 8 || used > minimum) { Count("domain-guard"); return; }
            var entries = new List<(int Dose,int Cost)>();
            for (int slot=0; slot<slots; slot++)
            {
                PotionModel? potion = combat.GetPotionAtSlot(player,slot);
                if (potion is null) continue;
                entries.Add((potion.GetType()==typeof(RegenPotion)
                    ? Math.Max(0,potion.DynamicVars["RegenPower"].IntValue) : 0,
                    PotionUsePolicy.StrategicHpCost(potion, root.HasRenewablePotionShapedRock)));
            }
            if (needed > entries.Count) { Count("insufficient-stock-kept"); return; }
            var options = new List<(long Dose,int Cost)>();
            void Visit(int index,int remaining,long dose,int cost)
            {
                if (remaining==0) {options.Add((dose,cost));return;}
                for (int i=index; i<=entries.Count-remaining; i++)
                    Visit(i+1,remaining-1,dose+entries[i].Dose,checked(cost+entries[i].Cost));
            }
            Visit(0,needed,0,node.Snapshot.ExplicitPotionStrategicCost);
            int post = root.PostCombatRelicHeal.UnconditionalHeal+root.PostCombatRelicHeal.WoundedHeal;
            int Lower(long dose) => ActEndingBossPolicy.StrategicHpDeficit(
                node.Snapshot.CumulativePlayerHpLost,0,
                StrategicHpRecoveryBound.OptimisticRecoveredHp(node.Snapshot.RecoveredPlayerHp,
                    node.Snapshot.PlayerHp,node.Snapshot.PlayerMaxHp,
                    StrategicHpRecoveryBound.RegenerationHealingUpperBound(active+dose,post)),
                relief,node.Snapshot.DeathSaveHpRestored);
            int Required(int cost) => PotionUsePolicy.SmartRequiredHpSaved(
                PotionUsePolicy.ApplyReplacementCredit(cost,minimum,root.PotionRewardOutlook.ReplacementHpCredit),relief);
            long separate = (long)Lower(options.Max(p=>p.Dose))+Required(options.Min(p=>p.Cost))-win.HpDeficit;
            long joint = options.Min(p=>(long)Lower(p.Dose)+Required(p.Cost)-win.HpDeficit);
            if (separate > joint) throw new InvalidOperationException("Joint mathematical inequality contradicted.");
            Count("finite-options");
            if (options.Select(p=>p.Dose).Distinct().Count()>1) Count("mixed-recovery-options");
            if (separate < joint) Count("joint-tighter");
            if (separate <= 0 && joint > 0) Count("joint-extra-potential");
            if (joint > 0) Count("potential-qualification-rejection");
            if (joint == 0) Count("equality-kept");
            if (options.Min(p=>p.Cost)!=stockCost) Count("branch-cost-versus-frozen-cost-difference");
        }
        finally { Interlocked.Add(ref _queryTicks,System.Diagnostics.Stopwatch.GetTimestamp()-began); }
    }
}

FiniteRecoveryDiagnostics.cs.text:
using System.Diagnostics;
using System.Text.Json;
namespace CombatSolver;
internal static class FiniteRecoveryDiagnostics
{
    private static int _rootCalls,_rootAccepted,_healingCalls,_unknownHealing;
    private static long _rootTicks,_queryTicks;
    private static readonly List<object> Solvers=[];
    static FiniteRecoveryDiagnostics()
    {
        AppDomain.CurrentDomain.ProcessExit+=(_,_)=>
        {
            string? path=Environment.GetEnvironmentVariable("COMBATSOLVER_FINITE_DIAGNOSTIC_OUTPUT");
            if (path is null) return;
            File.WriteAllText(path,JsonSerializer.Serialize(new
            {
                rootCalls=_rootCalls,rootAccepted=_rootAccepted,
                rootMilliseconds=(double)_rootTicks*1000/Stopwatch.Frequency,
                branchQueries=_healingCalls,unknownHealing=_unknownHealing,
                branchQueryMilliseconds=(double)_queryTicks*1000/Stopwatch.Frequency,
                solvers=Solvers,scope="Separate diagnostic: cumulative wall ticks, not performance acceptance or CPU",
            },new JsonSerializerOptions {WriteIndented=true}));
        };
    }
    internal static void Root(bool accepted,long began)
    {
        Interlocked.Increment(ref _rootCalls);if (accepted) Interlocked.Increment(ref _rootAccepted);
        Interlocked.Add(ref _rootTicks,Stopwatch.GetTimestamp()-began);
    }
    internal static void Query(int healing,long began)
    {
        Interlocked.Increment(ref _healingCalls);if (healing==int.MaxValue) Interlocked.Increment(ref _unknownHealing);
        Interlocked.Add(ref _queryTicks,Stopwatch.GetTimestamp()-began);
    }
    internal static void Solver(bool enabled,int? ceiling,int minimum,int? maximum,int finitePruned,int totalPruned,int stockExtra)
    {lock(Solvers)Solvers.Add(new {enabled,ceiling,minimum,maximum,finitePruned,totalPruned,stockExtra});}
}

