using CombatSolver.Engine.Common;
using System.Reflection;
using System.Reflection.Emit;
using HarmonyLib;
using MegaCrit.Sts2.Core.Combat;
using MegaCrit.Sts2.Core.Commands;
using MegaCrit.Sts2.Core.Entities.Cards;
using MegaCrit.Sts2.Core.Entities.Players;
using MegaCrit.Sts2.Core.Models;
using MegaCrit.Sts2.Core.Models.CardPools;
using MegaCrit.Sts2.Core.Models.Cards;

namespace CombatSolver;
internal sealed partial class UnattendedTestRunner
{
    private async Task AssertFutureGenerationPatchAuditAsync(CombatState live, Player player)
    {
        foreach (var relic in player.Relics.ToArray()) await RelicCmd.Remove(relic);
        foreach (var power in live.Creatures.SelectMany(c => c.Powers).ToArray()) await PowerCmd.Remove(power);
        await ClearPlayerPilesAsync(player);
        foreach (string id in new[] { "BUNDLE_OF_JOY", "ENTROPY", "DEFEND_REGENT" })
            await InjectCardAsync(live, player, new() { CardId=id, Pile="Hand", TreatAsDeckCard=true });
        foreach (var potion in player.PotionSlots.ToArray()) potion?.Discard();
        InjectPotionForTest(player, "HEART_OF_IRON");
        InjectPotionForTest(player, "REGEN_POTION");
        await CreatureCmd.SetCurrentHp(player.Creature, 35);
        CardModel future = ModelDb.Card<SecretWeapon>();
        if (!future.CanBeGeneratedInCombat
            || !ModelDb.CardPool<ColorlessCardPool>().GetUnlockedCards(player.UnlockState,
                player.RunState.CardMultiplayerConstraint).Any(c => c.GetType() == future.GetType())
            || player.PlayerCombatState!.AllCards.Concat(player.Deck.Cards).Any(c => c.GetType()==future.GetType()))
            throw new InvalidOperationException("Future type is not reachable or already initial.");
        var clean = CombatRootSnapshot.Capture(live);
        if (clean.ClosedPotionInventory is null) throw new InvalidOperationException("Clean stock fixture not certified.");
        MethodInfo target = AdaptedCardOnPlayMirrors.ResolveOnPlay(future.GetType())!;
        var assembly = AssemblyBuilder.DefineDynamicAssembly(new AssemblyName("UnregisteredFutureCardPatch"), AssemblyBuilderAccess.Run);
        var builder = assembly.DefineDynamicModule("probe").DefineType("UnregisteredFutureCardPatch.Source",TypeAttributes.Public);
        var method = builder.DefineMethod("Prefix",MethodAttributes.Public|MethodAttributes.Static,typeof(bool),Type.EmptyTypes);
        var il = method.GetILGenerator(); il.Emit(OpCodes.Ldc_I4_0); il.Emit(OpCodes.Ret);
        MethodInfo prefix = builder.CreateType()!.GetMethod("Prefix")!;
        var harmony = new Harmony("combatsolver.research.unregistered-future-onplay");
        try
        {
            harmony.Patch(target, prefix:new HarmonyMethod(prefix));
            bool directAuditRejects=false;
            try { PredictionModPatchAudit.AuditCardOnPlay(future.GetType(), false, out _); }
            catch (PredictionUnsupportedException) { directAuditRejects=true; }
            if (!directAuditRejects) throw new InvalidOperationException("Unknown patch control was not rejected.");
            var admitted = CombatRootSnapshot.Capture(live);
            var sim = admitted.ForkSimulator();
            int healing = StrategicHpRecoveryBound.ComponentHealingUpperBound(sim, player, 0);
            bool admittedUnknownFuture = admitted.ClosedPotionInventory is not null && healing==15;
            if (!admittedUnknownFuture) throw new InvalidOperationException("Expected admission gap did not reproduce.");
            Entry.Logger.Info("FUTURE_GENERATION_PATCH_AUDIT_REPRODUCED type=SecretWeapon initial=false native_reachable=true direct_audit_rejected=true root_stock_certified=true healing=15");
        }
        finally { harmony.Unpatch(target, HarmonyPatchType.All, harmony.Id); }
    }
}

