using CombatSolver.Engine.Common;
using CombatSolver.Engine.InCombat.Simulation;
using MegaCrit.Sts2.Core.Combat;
using MegaCrit.Sts2.Core.Commands;
using MegaCrit.Sts2.Core.Entities.Cards;
using MegaCrit.Sts2.Core.Entities.Players;
using MegaCrit.Sts2.Core.GameActions;
using MegaCrit.Sts2.Core.GameActions.Multiplayer;
using MegaCrit.Sts2.Core.Hooks;
using MegaCrit.Sts2.Core.Models;
using MegaCrit.Sts2.Core.Models.Afflictions;
using MegaCrit.Sts2.Core.Models.Cards;
using MegaCrit.Sts2.Core.Models.Potions;
using MegaCrit.Sts2.Core.Models.Powers;
using MegaCrit.Sts2.Core.Nodes;

namespace CombatSolver;

internal sealed partial class UnattendedTestRunner
{
    private async Task AssertInitialGenerationInventoryAsync(CombatState live, Player player)
    {
        foreach (var relic in player.Relics.ToArray()) await RelicCmd.Remove(relic);
        foreach (var power in live.Creatures.SelectMany(creature => creature.Powers).ToArray())
            await PowerCmd.Remove(power);
        await ClearPlayerPilesAsync(player);
        foreach (string id in new[] { "BUNDLE_OF_JOY", "ENTROPY", "DEFEND_REGENT" })
            await InjectCardAsync(live, player, new() { CardId = id, Pile = "Hand", TreatAsDeckCard = true });
        foreach (var potion in player.PotionSlots.ToArray()) potion?.Discard();
        InjectPotionForTest(player, "HEART_OF_IRON");
        InjectPotionForTest(player, "REGEN_POTION");
        SetEnergy(player, 20);
        SetStars(player, 20);
        await CreatureCmd.SetCurrentHp(player.Creature, 35);
        CombatRootSnapshot root = CombatRootSnapshot.Capture(live);
        var parent = root.ForkSimulator();
        string? oldRejection = StrategicHpRecoveryBound.ComponentRootSourceRejection(
            parent, player, requireClosedPotionInventory: true);
        if (oldRejection != "initial-card:BundleOfJoy" || root.ClosedPotionInventory is not { } stock)
            throw new InvalidOperationException($"Initial generation stock proof: {oldRejection}, {root.ComponentHealingRejection}.");
        string Stamp(CombatPredictionSimulator sim) => DescribeContinuationContractState(sim, root, player);
        int Bound(CombatPredictionSimulator sim, bool include = true, int? cap = null)
            => StrategicHpRecoveryBound.ComponentHealingUpperBound(sim, player, 0,
                includePotionHealing: include, maximumExplicitPotionUses: cap);
        int? Cost(CombatPredictionSimulator sim, int count)
            => stock.MinimumExplicitCost(sim, player, count, Bound(sim));
        string parentBefore = Stamp(parent), liveBefore = ContinuationStamp.CaptureLive(live).StateText;
        int heartCost = PotionUsePolicy.StrategicHpCost(ModelDb.Potion<HeartOfIron>());
        int regenCost = PotionUsePolicy.StrategicHpCost(ModelDb.Potion<RegenPotion>());
        void Equal(string expected, string actual, string label)
        {
            if (expected != actual) throw new InvalidOperationException($"Initial inventory {label}:\nEXPECTED\n{expected}\nACTUAL\n{actual}");
        }
        CombatPredictionSimulator Use(CombatPredictionSimulator from, int slot)
        {
            using var isolation = SimulationNotificationIsolation.Enter();
            var sim = from.Fork(); var combat = (SimulatedCombatState)sim.State.CombatState;
            PotionModel potion = combat.GetPotionAtSlot(player, slot)!;
            combat.BeginActionChoices((IReadOnlyList<PlanCardChoice>?)null);
            try
            {
                int history = sim.History.Entries.Count;
                if (!PotionExecutionSupport.Prepare(sim, combat, potion, slot, player.Creature)
                    || !PotionExecutionSupport.Complete(sim, combat, potion, player.Creature, null,
                        history, new ForkableSet<uint>())
                    || !CombatBeamSolver.SettleReplayActionBoundary(sim, combat))
                    throw new InvalidOperationException("Stock potion replay unexpectedly suspended.");
            }
            finally { combat.EndActionChoices(); }
            return sim;
        }
        using (SimulationNotificationIsolation.Enter())
        {
            if (Bound(parent) != 15 || Bound(parent, false) != 0
                || Cost(parent, 1) != Math.Min(heartCost, regenCost)
                || Cost(parent, 2) != heartCost + regenCost)
                throw new InvalidOperationException("Initial source/dose/cost proof incorrect.");
            foreach (PileType pile in new[] { PileType.Hand, PileType.Draw, PileType.Discard, PileType.Exhaust })
            {
                var unknown = parent.Fork();
                unknown.AddGeneratedCardToCombat(PredictedCard.Create(ModelDb.Card<Alchemize>(), player),
                    pile, player, resultKind: CardGenerationResultKind.Fixed);
                if (Bound(unknown) != int.MaxValue || Cost(unknown, 1) is not null
                    || ClosedInitialPotionInventory.Capture(unknown, player, false) is not null)
                    throw new InvalidOperationException("Unknown initial/branch acquisition accepted in " + pile);
            }
            var attached = parent.Fork();
            attached.Afflict<Hexed>(attached.State.GetPlayerCombatState(player).Hand.Cards[0], 1);
            if (Bound(attached) != int.MaxValue || Cost(attached, 1) is not null)
                throw new InvalidOperationException("Unknown attached source accepted.");
            var heart = Use(parent, 0);
            if (Bound(heart, cap: 1) != 0 || Bound(heart, cap: 2) != 15)
                throw new InvalidOperationException("Unused dose was not constrained by explicit use cap.");
            var active = heart.Fork();
            ((SimulatedCombatState)active.State.CombatState).SetAmount<RegenPower>(player.Creature, 3);
            if (Bound(active, false, 1) != 6)
                throw new InvalidOperationException("Active regeneration was removed with unusable potions.");
            var refill = heart.Fork();
            ((SimulatedCombatState)refill.State.CombatState).TryProcurePotion(player, ModelDb.Potion<HeartOfIron>());
            if (Cost(refill, 2) is not null)
                throw new InvalidOperationException("Same-ID replenishment accepted.");
            var free = heart.Fork();
            ((SimulatedCombatState)free.State.CombatState).TryProcurePotion(player,
                ModelDb.Potion<HeartOfIron>(), freeFromEntropic: true);
            if (Cost(free, 2) is not null || ClosedInitialPotionInventory.Capture(free, player, false) is not null)
                throw new InvalidOperationException("Free unknown source accepted.");
        }
        var potionChildren = Enumerable.Range(0,16).Select(_ => parent.Fork()).ToArray();
        await Task.WhenAll(potionChildren.Select((child,index) => Task.Run(() =>
        {
            var first = Use(child, index % 2);
            var both = Use(first, 1-index % 2);
            if (Cost(first, 2) != heartCost+regenCost || Cost(both, 2) != heartCost+regenCost)
                throw new InvalidOperationException("Parallel potion-order stock differed.");
            Equal(Stamp(both), Stamp(both.Fork()), "grandchild full state/history/RNG");
            Equal(parentBefore, Stamp(child), "unmodified child parent");
        })));
        Equal(parentBefore, Stamp(parent), "frozen parent after parallel uses");
        Equal(liveBefore, ContinuationStamp.CaptureLive(live).StateText, "live after simulated uses");

        var prediction = parent.Fork();
        using var deadline = new CancellationTokenSource(TimeSpan.FromSeconds(25));
        foreach (string id in new[] { "BUNDLE_OF_JOY", "ENTROPY" })
        {
            CardModel native = player.PlayerCombatState!.Hand.Cards.Single(card => card.Id.Entry == id);
            if (native.DeckVersion is null) throw new InvalidOperationException("Initial deck identity missing.");
            using (SimulationNotificationIsolation.Enter())
            {
                var combat = (SimulatedCombatState)prediction.State.CombatState;
                var card = prediction.State.GetPlayerCombatState(player).Hand.Cards.Single(c => c.Preview.Id.Entry == id);
                using (combat.BeginCardExecutionScope(new ForkableSet<uint>()))
                    if (!prediction.ManualPlay(card, null, out _))
                        throw new InvalidOperationException("Initial card unexpectedly suspended: " + id);
                if (!CombatBeamSolver.SettleReplayActionBoundary(prediction, combat)
                    || Cost(prediction, 2) != heartCost+regenCost)
                    throw new InvalidOperationException("Initial card invalidated reviewed stock: " + id);
            }
            string expected = ContinuationStamp.CapturePredicted(player, prediction, root.StartTurnNumber,
                root.Forecast, root.StartTurnNumber).StateText;
            GameAction action = await SolverController.EnqueueAndCaptureActionAsync(
                queued => queued is PlayCardAction played && ReferenceEquals(played.NetCombatCard.ToCardModelOrNull(), native),
                () => { if (!native.TryManualPlay(null)) throw new InvalidOperationException("Native card refused: " + id); },
                deadline.Token);
            await action.CompletionTask.WaitAsync(deadline.Token);
            Equal(expected, ContinuationStamp.CaptureLive(live).StateText, "native " + id);
        }
        var names = SolverDisplayNames.Capture(live);
        CombatPredictionSimulator Trigger(CombatPredictionSimulator from, IReadOnlyList<PlanCardChoice>? choices)
        {
            using var isolation = SimulationNotificationIsolation.Enter();
            var sim = from.Fork(); var combat = (SimulatedCombatState)sim.State.CombatState;
            combat.BeginActionChoices(choices);
            try
            {
                combat.TriggerAfterPlayerTurnStart(sim, player.Creature, combat.ActiveExecutionChoices);
                if (!sim.HasPendingChoice) CombatBeamSolver.SettleReplayActionBoundary(sim, combat);
            }
            finally { combat.EndActionChoices(); }
            return sim;
        }
        var pending = Trigger(prediction, null);
        var request = ((SimulatedCombatState)pending.State.CombatState).PendingTurnStartChoice
            ?? throw new InvalidOperationException("Entropy turn callback did not request selection.");
        if (request.SourceId != "ENTROPY_POWER" || Cost(pending, 2) is not null)
            throw new InvalidOperationException("Unknown pending selection was certified.");
        var choices = CardChoiceSupport.BuildChoices(request.Spec!, names, 128, 128)
            .Select(choice => choice with { SourceId=request.SourceId, Timing=request.Timing, ContextId=request.ContextId })
            .Where(choice => choice.Cards.Count > 0).ToArray();
        if (choices.Length < 2) throw new InvalidOperationException("Entropy alternatives missing.");
        string predictionBefore = Stamp(prediction), liveAtCallback = ContinuationStamp.CaptureLive(live).StateText;
        var expectedBranches = choices.Select(choice => Trigger(prediction, [choice])).ToArray();
        var callbackChildren = Enumerable.Range(0,16).Select(_ => prediction.Fork()).ToArray();
        await Task.WhenAll(callbackChildren.Select((child,index) => Task.Run(() =>
        {
            var sim = Trigger(child, [choices[index % choices.Length]]);
            Equal(Stamp(expectedBranches[index % choices.Length]), Stamp(sim), "parallel transform");
            Equal(Stamp(sim), Stamp(sim.Fork()), "transformed grandchild");
            if (Cost(sim,2) != heartCost+regenCost)
                throw new InvalidOperationException("Native generated/transform closure lost stock.");
        })));
        Equal(predictionBefore, Stamp(prediction), "callback parent");
        Equal(liveAtCallback, ContinuationStamp.CaptureLive(live).StateText, "callback live");
        using (var session = NativeChoiceRuntime.Begin(live, player, "test:initial-generation-inventory"))
        {
            session.SetPlanAndStartDriving(NGame.Instance!, [choices[0]], deadline.Token);
            await session.AwaitProducerAndCompleteAsync(
                Hook.AfterPlayerTurnStart(live, new BlockingPlayerChoiceContext(), player)).WaitAsync(deadline.Token);
        }
        Equal(ContinuationStamp.CapturePredicted(player, expectedBranches[0], root.StartTurnNumber,
            root.Forecast, root.StartTurnNumber).StateText, ContinuationStamp.CaptureLive(live).StateText,
            "native Entropy transform callback");
        Equal(parentBefore, Stamp(parent), "original root after all native actions");
        await InjectCardAsync(live, player, new() { CardId="ALCHEMIZE", Pile="Exhaust", TreatAsDeckCard=true });
        if (CombatRootSnapshot.Capture(live).ClosedPotionInventory is not null)
            throw new InvalidOperationException("Unknown initial deck/exhaust source accepted.");
        _completedChecks.Add("InitialGenerationInventory:IndependentInitialCardProof:DeckVersions:KnownGenerationAndCombatTransform:TwoNativeFullPlays:NativeEntropyCallback:AllFourUnknownPiles:UnknownInitialDeck:UnknownAttachment:PendingRefused:SameIdRefillAndFreeRefused:ActiveRegenAndCap:32SerialForkChildrenParallelMutations:GrandchildrenFullHistoryRng:ParentLiveIsolation");
    }
}

using System.Reflection;
using HarmonyLib;
using CombatSolver.Engine.Common;
using CombatSolver.Engine.InCombat.Simulation;
using MegaCrit.Sts2.Core.Combat;
using MegaCrit.Sts2.Core.Commands;
using MegaCrit.Sts2.Core.Entities.Cards;
using MegaCrit.Sts2.Core.Entities.Players;
using MegaCrit.Sts2.Core.GameActions;
using MegaCrit.Sts2.Core.GameActions.Multiplayer;
using MegaCrit.Sts2.Core.Models;
using MegaCrit.Sts2.Core.Models.Cards;
using MegaCrit.Sts2.Core.Models.Potions;
using MegaCrit.Sts2.Core.Models.Powers;
using MegaCrit.Sts2.Core.ValueProps;

namespace CombatSolver;

internal sealed partial class UnattendedTestRunner
{
    private static Action? _finiteSmartEndObserver;
    private static void ObserveFiniteSmartEndPrefix() => _finiteSmartEndObserver?.Invoke();
    private async Task AssertFiniteSmartConsumerAsync(CombatState live, Player player)
    {
        foreach (var relic in player.Relics.ToArray()) await RelicCmd.Remove(relic);
        foreach (var power in live.Creatures.SelectMany(creature => creature.Powers).ToArray())
            await PowerCmd.Remove(power);
        await ClearPlayerPilesAsync(player);
        foreach (string id in new[] {"BUNDLE_OF_JOY","ENTROPY","OFFERING","BLOODLETTING","STRIKE_REGENT"})
            await InjectCardAsync(live,player,new() {CardId=id,Pile="Hand",TreatAsDeckCard=true});
        foreach (var potion in player.PotionSlots.ToArray()) potion?.Discard();
        InjectPotionForTest(player,"HEART_OF_IRON"); InjectPotionForTest(player,"REGEN_POTION");
        SetEnergy(player,20); SetStars(player,20);
        await CreatureCmd.SetCurrentHp(live.Enemies.Single(),6);
        await CreatureCmd.SetCurrentHp(player.Creature,35);
        BattleDamageTracker.Begin(live);
        var damage=BattleDamageTracker.Observe(live);
        var root=CombatRootSnapshot.Capture(live);
        if (damage.HpLostSoFar!=0 || root.ClosedPotionInventory is null
            || root.UsesComponentHealingCertificate)
            throw new InvalidOperationException("Finite Smart fixture did not take the new independent source proof.");
        string before=ContinuationStamp.CaptureLive(live).StateText;
        var parent=root.ForkSimulator(); string parentBefore=DescribeContinuationContractState(parent,root,player);
        var names=SolverDisplayNames.Capture(live);
        var policy=SolverController.CaptureSearchPolicy(SolverSettings.Capture(),live,false,null) with
        {
            FixedBudget=true,VerifyIncrementalSearch=true,MaxDegreeOfParallelism=2,
            DetailedDiagnostics=false,MeasurePhasePerformance=false,BudgetOverrideMilliseconds=null,
            StopAtAcceptableBattleHpLoss=false,UseBeamWidthPortfolio=true,BeamWidthPortfolioWidths=[8,12],
            UseNoveltyPortfolio=false,PotionPolicy=SolverPotionPolicy.Smart,
            PotionStrategy=new(SolverPotionPolicy.Smart,[]),RelicTargets=[],GrowthBudgets=default,
            GrowthOpportunityTargets=GrowthOpportunityTargets.Empty,
            DisableSharedPrimaryIncumbentsForTesting=true,
        };
        policy=policy with {Profile=policy.Profile with
            {BeamWidth=8,MaxExpandedNodes=160,SoftTimeBudgetMilliseconds=10000,StopPortfolioAtHpTarget=false}};
        using var deadline=new CancellationTokenSource(TimeSpan.FromSeconds(25));
        var proof=CombatBeamSolver.AssertFiniteSmartConsumerForTesting(root,names,damage,policy,deadline.Token);
        if (ContinuationStamp.CaptureLive(live).StateText!=before
            || DescribeContinuationContractState(parent,root,player)!=parentBefore)
            throw new InvalidOperationException("Finite consumer changed parent/live/full history/RNG.");
        var result=await Task.Run(()=>CombatSearchCoordinator.Solve(root,names,damage,policy,deadline.Token,null));
        if (!result.Snapshot.AllEnemiesDead || result.Snapshot.PlayerDead || result.Snapshot.HasRisk
            || result.ExplicitPotionCount!=0 || result.ProjectedBattleHpLost!=0
            || result.Snapshot.ProjectedDeathSaveUseCount!=0
            || ContinuationStamp.CaptureLive(live).StateText!=before)
            throw new InvalidOperationException("Finite Smart coordinator changed complete no-potion victory.");
        string? terminalBeforeCleanup=null;
        MethodInfo endCombat=typeof(CombatManager).GetMethods(BindingFlags.Instance|BindingFlags.NonPublic)
            .Single(method=>method.Name=="EndCombatInternal"
                && method.GetParameters() is [{ParameterType.Name:"CombatTurnState"}]);
        Harmony observerPatch=new("CombatSolver.Testing.FiniteSmartTerminal."+_request.RunId);
        _finiteSmartEndObserver=()=>terminalBeforeCleanup=ContinuationStamp.CaptureLive(live).StateText;
        try
        {
            observerPatch.Patch(endCombat,prefix:new HarmonyMethod(typeof(UnattendedTestRunner).GetMethod(
                nameof(ObserveFiniteSmartEndPrefix),BindingFlags.Static|BindingFlags.NonPublic)!));
            foreach (string id in new[] {"OFFERING","BLOODLETTING","STRIKE_REGENT"})
            {
                CardModel native=player.PlayerCombatState!.Hand.Cards.Single(c=>c.Id.Entry==id);
                GameAction action=await SolverController.EnqueueAndCaptureActionAsync(
                    queued=>queued is PlayCardAction played && ReferenceEquals(played.NetCombatCard.ToCardModelOrNull(),native),
                    ()=> {if (!native.TryManualPlay(id=="STRIKE_REGENT" ? live.Enemies.Single() : null))
                        throw new InvalidOperationException("Native witness refused: "+id);},deadline.Token);
                await action.CompletionTask.WaitAsync(deadline.Token);
            }
            string actual=terminalBeforeCleanup??throw new InvalidOperationException("Native terminal boundary not observed.");
            if (proof.NativeWinnerStamp!=actual)
            {
                var differences=new ContinuationStamp(proof.NativeWinnerStamp)
                    .DescribeDifferences(new ContinuationStamp(actual));
                throw new InvalidOperationException("Native pre-teardown witness full-state differences: "
                    +string.Join("\n",differences));
            }
        }
        finally {observerPatch.UnpatchAll(observerPatch.Id);_finiteSmartEndObserver=null;}
        _completedChecks.Add(proof.Checks+":StrictReplay:Dop2WholeCoordinator:NativePreTeardownCompleteWitnessFullState:ParentLiveHistoryRngIsolation");
    }
}

internal sealed partial class CombatBeamSolver
{
    internal static (string NativeWinnerStamp,string Checks) AssertFiniteSmartConsumerForTesting(
        CombatRootSnapshot root,SolverDisplayNames names,BattleDamageSnapshot damage,SearchPolicySnapshot policy,
        CancellationToken token)
    {
        using var isolation=SimulationNotificationIsolation.Enter();
        var player=root.PlayerIdentity;
        var publisher=new CombatBeamSolver(root,names,damage,policy,token,
            potionPolicyOverride:SolverPotionPolicy.Disabled,maximumPotionUses:0);
        var opening=CreateOpeningSearchSeed(publisher.Replay([]));
        var strike=publisher.PrepareCardActions(opening).First(a=>a.Action.CardId=="STRIKE_REGENT").Action;
        var paid=publisher.CostChildForTesting(opening,
            publisher.PrepareCardActions(opening).First(a=>a.Action.CardId=="OFFERING").Action);
        paid=publisher.CostChildForTesting(paid,
            publisher.PrepareCardActions(paid).First(a=>a.Action.CardId=="BLOODLETTING").Action);
        var winner=publisher.CostChildForTesting(paid,strike);
        if (!winner.Snapshot.AllEnemiesDead || winner.Snapshot.PlayerDead || winner.Snapshot.HasRisk
            || winner.Snapshot.PotionUseCount!=0 || winner.Snapshot.DeathSaveUseCount!=0)
            throw new InvalidOperationException("Missing complete compliant no-potion witness.");
        int deficit=StrategicHpLowerBound(winner.Snapshot,BossHpRelief.None,0);
        if (deficit!=9) throw new InvalidOperationException("Fixture witness deficit incorrect: "+deficit);
        var baseline=new PotionFreePolicyBaseline(true,deficit,winner.Snapshot.PlayerHp,winner.Turn);
        CombatBeamSolver Solver(SearchPolicySnapshot p,PotionFreePolicyBaseline? b=null,
            DirectSearchPurpose purpose=DirectSearchPurpose.SmartPotionGradient,int minimum=1,int maximum=1)
            => new(root,names,damage,p,token,potionPolicyOverride:SolverPotionPolicy.RequireAtLeastOne,
                potionFreePolicyBaseline:b??baseline,minimumPotionUses:minimum,maximumPotionUses:maximum,
                directSearchPurpose:purpose);
        var consumer=Solver(policy);
        if (!consumer._finiteRecoverySmartEligibility || !consumer.ComponentSmartBoundEnabledForTesting)
            throw new InvalidOperationException("Finite exact consumer not enabled.");
        var seed=CreateOpeningSearchSeed(consumer.Replay([]));
        var heart=consumer.CostChildForTesting(seed,
            consumer.PreparePotionActions(seed).Single(a=>a.Action.PotionSlot==0).Action);
        heart=consumer.CostChildForTesting(heart,
            consumer.PrepareCardActions(heart).First(a=>a.Action.CardId=="OFFERING").Action);
        var regen=consumer.CostChildForTesting(seed,
            consumer.PreparePotionActions(seed).Single(a=>a.Action.PotionSlot==1).Action);
        int Kept(CombatBeamSolver s,SearchNode node)=>s.ApplySmartPotionEligibilityBound([node]).Count;
        if (Kept(consumer,seed)!=1 || Kept(consumer,heart)!=0 || Kept(consumer,regen)!=1
            || consumer.FiniteRecoveryEligibilityPrunedForTesting<1)
            throw new InvalidOperationException("Unused dose cap or actual active Regen consumer failed.");
        SearchNode Mutate(SearchNode source,Action<CombatPredictionSimulator> mutate)
        {
            var sim=(CombatPredictionSimulator)source.Snapshot.Simulator.Fork();mutate(sim);
            var snap=consumer.Snapshot(sim,source.Turn,source.ActionCount,source.Snapshot.ShufflesCrossed,
                SearchBoundaryReason.None,source.Snapshot.ProcessedEnemyDeaths);
            return source with {Snapshot=snap,StateKey=snap.StateKey,Score=snap.Score};
        }
        foreach (PileType pile in new[] {PileType.Hand,PileType.Draw,PileType.Discard,PileType.Exhaust})
        {
            var unknown=Mutate(heart,sim=>sim.AddGeneratedCardToCombat(PredictedCard.Create(ModelDb.Card<Alchemize>(),player),
                pile,player,resultKind:CardGenerationResultKind.Fixed));
            if (Kept(consumer,unknown)!=1) throw new InvalidOperationException("Unknown source consumer pruned "+pile);
        }
        foreach (bool free in new[] {false,true})
        {
            var refill=Mutate(heart,sim=>((SimulatedCombatState)sim.State.CombatState).TryProcurePotion(player,
                ModelDb.Potion<HeartOfIron>(),freeFromEntropic:free));
            if (Kept(consumer,refill)!=1) throw new InvalidOperationException("Refill/free consumer incorrectly pruned.");
        }
        // Synthetic typed boundary states test arithmetic, not claimed playable routes.
        var equality=Mutate(heart,sim=>
        {
            sim.Heal(player.Creature,3);
            ((SimulatedCombatState)sim.State.CombatState).SetAmount<RegenPower>(player.Creature,2);
        });
        var strictlyWorse=Mutate(heart,sim=>
        {
            sim.Heal(player.Creature,3);
            ((SimulatedCombatState)sim.State.CombatState).SetAmount<RegenPower>(player.Creature,1);
        });
        if (Kept(consumer,equality)!=1 || Kept(consumer,strictlyWorse)!=0)
            throw new InvalidOperationException("Equality must stay; only strict impossibility may be pruned.");
        foreach (var guarded in new[]
        {
            policy with {PotionPolicy=SolverPotionPolicy.Disabled},
            policy with {PotionPolicy=SolverPotionPolicy.RequireAtLeastOne},
            policy with {TheftPolicy=SolverTheftPolicy.PreserveResources},
            policy with {GrowthBudgets=new GrowthValues(Feed:1)},
            policy with {GrowthOpportunityTargets=GrowthOpportunityTargets.UnboundedForTesting("finite_guard")},
            policy with {RelicTargets=[new(RelicCounterId.MeatOnTheBone,0,1,0,2)]},
            policy with {PotionStrategy=new(SolverPotionPolicy.Smart,[new(0,"HEART_OF_IRON",SolverPotionDirective.Force)])},
        })
            if (Solver(guarded).ComponentSmartBoundEnabledForTesting)
                throw new InvalidOperationException("Finite consumer policy/target guard ignored.");
        foreach (var guarded in new[] {Solver(policy,baseline with {Won=false}),
            Solver(policy,baseline with {DeathSaveUseCount=1}),Solver(policy,purpose:DirectSearchPurpose.PrimaryBeam),
            Solver(policy,minimum:1,maximum:2)})
            if (guarded.ComponentSmartBoundEnabledForTesting || Kept(guarded,heart)!=1)
                throw new InvalidOperationException("Missing witness, death save, ordinary purpose or nonexact use ignored.");
        return (ContinuationStamp.CapturePredicted(player,(CombatPredictionSimulator)winner.Snapshot.Simulator,
            root.StartTurnNumber,root.Forecast,root.StartTurnNumber).StateText,
            "FiniteSmartConsumer:IndependentInventorySource:CompleteP0Witness:ActualHeartCut:ActualRegenKept:ActiveRegenEqualityKept:StrictImpossibilityCut:FourUnknownPilesKept:RefillFreeKept:SmartDisabledForcedGrowthRelicTheftPurposeNonexactDeathSaveGuards");
    }
}

